/* Native-dialog appearance in the empty-Part state. Geometry commits are deliberately unavailable. */
(()=>{'use strict';
const ui=window.asaNativeUI,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const box=document.createElement('section');box.id='nativeParams';box.className='native-params';box.setAttribute('role','dialog');box.setAttribute('aria-modal','false');box.hidden=true;document.body.append(box);
let current=null,collapsed=false,pos=null,drag=null;const states=new Map();const dip=96/110;const widths=new Map();
const field=(id,name,kind,value,options=[])=>({id,name,kind,value,options});
const pick=(id,name)=>field(id,name,'pick','');const check=(id,name,v=true)=>field(id,name,'check',v);const choice=(id,name,v,opts)=>field(id,name,'choice',v,opts);const buttons=(id,name,v,opts)=>field(id,name,'buttons',v,opts);
const operation=()=>choice('operation','Операция','Новое тело',['Объединение','Вырезание','Пересечение','Новое тело']);
const schemas={
 Extrude:{width:286,preset:true,fields:[buttons('type','Тип','Сплошное',['Сплошное','Тонкостенное']),pick('profile','Профили'),check('chain','Цепочка'),choice('start','Начало','Плоскость профиля',['Плоскость профиля','Смещение','Объект']),choice('direction','Направление','В одну сторону',['В одну сторону','В две стороны','Симметрично']),choice('extent','Протяжённость','Расстояние',['Расстояние','До объекта','Всё']),choice('wall','Сторона стенки','Сторона 1',['Сторона 1']),operation()]},
 Revolve:{width:286,fields:[pick('profile','Профиль'),pick('axis','Ось'),check('project','Проецировать ось'),operation()]},
 PatternRectangular:{width:286,fields:[buttons('type','Тип','Прямоугольный',['Прямоугольный','Круговой','По траектории']),choice('objectType','Тип объектов','Тела',['Тела']),pick('objects','Объекты'),pick('axes','Оси')]},
 FusionHoleCommand:{width:423,fields:[buttons('placement','Размещение','Одна точка',['Одна точка','Точки эскиза']),pick('faces','Грань/Точки эскиза'),field('shape','Параметры формы','section',true),choice('extent','Протяжённость','Расстояние',['Расстояние']),buttons('holeType','Тип отверстия','Простое',['Простое','Цековка','Зенковка']),buttons('tap','Резьба','Без резьбы',['Без резьбы','Посадка','Резьба','Коническая резьба']),buttons('drill','Вершина сверла','Коническая',['Плоская','Коническая'])]},
 FusionFilletEdgesCommand:{width:515,fields:[choice('type','Тип','Скругление',['Скругление']),field('sets','Наборы рёбер','set-list',[]),choice('radiusType','Тип радиуса','Постоянный',['Постоянный']),pick('edges','Рёбра/Грани/Элементы'),check('tangent','Цепочка касательных'),choice('corner','Тип угла','Катящийся шар',['Катящийся шар'])]},
 FusionShellBodyCommand:{width:286,preset:true,fields:[pick('faces','Грани/Тело'),check('tangent','Цепочка касательных'),buttons('type','Тип оболочки','Острая',['Острая','Скруглённая']),choice('direction','Направление','Внутрь',['Внутрь'])]},
 FusionCombineCommand:{width:286,fields:[pick('target','Целевое тело'),pick('tools','Тела-инструменты'),buttons('operation','Операция','Объединение',['Объединение','Вырезание','Пересечение']),check('keep','Сохранить инструменты',false)]},
 FusionSplitBodyCommand:{width:286,fields:[pick('body','Разделяемое тело'),pick('tool','Инструменты разделения'),check('extend','Продлить инструменты')]},
 FusionMoveCommand:{width:286,fields:[choice('object','Объекты перемещения','Тела',['Тела']),pick('selection','Выбор'),buttons('moveType','Тип перемещения','Свободно',['Свободно','Перенос','Вращение','От точки к точке','От точки к положению']),buttons('pivot','Центр перемещения','Задать',['Задать'])]},
 AutomatedModelingCommand:{width:378,fields:[field('inputs','Исходные данные','section',true),pick('connect','Соединяемые грани'),pick('avoid','Обходить тела'),operation(),field('generate','Создать варианты','disabled-action',null),field('alternatives','Варианты','section',true)]}
};
Object.assign(schemas,window.asaNativeConstruction?.schemas||{});
function data(){return states.get(current);}
function changeField(field,value){const target=window.asaNativeConstruction?.transition(current,field,value);if(target&&target!==current){ui.run(target);return;}data()[field]=value;render();}
function symbol(id,value){if(id==='geometryType')return window.asaNativeConstruction.typeArt(value);if(id==='planeDirection')return '<svg viewBox="0 0 24 24" width="22" height="22"><path d="M3 3h18v18H3Z" fill="#edf0ed" stroke="#8e9691"/><g transform="'+(value==='По V'?'rotate(90 12 12)':'')+'" fill="none" stroke="#8a9690" stroke-width="1.3"><path d="M4 6q5-3 9 2t7-1M4 11q6-2 9 2t7-1M4 16q6-2 9 2t7-1"/></g></svg>';if(id==='type'&&current==='Extrude')return value==='Сплошное'?window.asaNativeIcon.draw('Extrude',22):'<svg viewBox="0 0 28 28" width="22" height="22"><path d="m6 8 5-4h12v16l-5 4H6Z" fill="#73b9dd" stroke="#8a989f"/><path d="M10 8h8v14M6 8h12l5-4" fill="none" stroke="#e2edf3" stroke-width="2"/></svg>';if(id==='moveType')return {'Свободно':'✥','Перенос':'↗','Вращение':'⟳','От точки к точке':'↔','От точки к положению':'⌖'}[value];if(id==='pivot')return '⌖';if(id==='operation')return window.asaNativeIcon.draw('FusionCombineCommand',22);if(id==='placement')return value==='Одна точка'?'⊙':'⠿';if(id==='type'&&current==='PatternRectangular')return value==='Прямоугольный'?'⠿':value==='Круговой'?'◌':'⠔';return '<svg viewBox="0 0 24 24" width="21" height="21"><path d="M4 3h16v18H4Z" fill="#d6e7ef" stroke="#7c94a1"/><path d="M8 5v14h8V5" fill="#7aaec9" stroke="#7c94a1"/></svg>';}
function renderField(f){const state=data(),val=state[f.id];if(current==='Extrude'&&['chain','wall'].includes(f.id)&&state.type!=='Тонкостенное')return '';
 if(f.kind==='section')return `<button type="button" class="native-section" data-native-section="${f.id}" aria-expanded="${!!val}">${val?'▾':'▸'} ${esc(f.name)}</button>`;
 if(f.kind==='set-list')return '<div class="native-set-list" role="group" aria-label="Наборы рёбер"><div class="native-empty-set"></div><div><button type="button" data-native-select="edges" aria-label="Добавить набор рёбер">+</button><button type="button" disabled aria-label="Удалить набор">×</button></div></div>';
 if(f.kind==='disabled-action')return `<button class="native-disabled-action" type="button" disabled>${esc(f.name)}</button>`;
 const label=`<label id="nf-label-${f.id}">${esc(f.name)}</label>`;let ctl='';
 if(f.kind==='pick')ctl=`<button type="button" class="native-pick" data-native-select="${f.id}" aria-labelledby="nf-label-${f.id}"><span>↖</span> Выбрать</button>`;
 if(f.kind==='choice')ctl=`<button type="button" class="native-choice" data-native-field="${f.id}" aria-haspopup="listbox" aria-labelledby="nf-label-${f.id}">${f.id==='method'?'<i class="native-method-icon">'+window.asaNativeConstruction.commandArt(window.asaNativeConstruction.methodIcon(current,val),20)+'</i>':''}<span>${esc(val)}</span><b>⌄</b></button>`;
 if(f.kind==='check')ctl=`<input type="checkbox" data-native-check="${f.id}" aria-labelledby="nf-label-${f.id}" ${val?'checked':''}>`;
 if(f.kind==='buttons')ctl=`<div class="native-button-options" role="group" aria-labelledby="nf-label-${f.id}">${f.options.map(v=>`<button type="button" class="native-option ${v===val?'active':''}" data-native-option="${f.id}" data-option-value="${esc(v)}" aria-label="${esc(v)}" title="${esc(v)}" aria-pressed="${v===val}">${symbol(f.id,v)}</button>`).join('')}</div>`;
 return `<div class="native-field" data-field-row="${f.id}">${label}<div class="native-field-control">${ctl}</div></div>`;
}
function render(){if(!current)return;const spec=schemas[current];box.dataset.nativeCommand=current;box.dataset.family=spec?.family||'';box.setAttribute('aria-label',ui.label(current));box.style.width=(widths.get(current)||Math.max(250,Math.round((spec?.width||330)*dip)))+'px';
 let body=spec?spec.fields.filter(f=>{if(current==='FusionHoleCommand'&&data().shape===false&&['extent','holeType','tap','drill'].includes(f.id))return false;if(current==='AutomatedModelingCommand'&&data().inputs===false&&['connect','avoid','operation','generate'].includes(f.id))return false;return true;}).map(renderField).join(''):`<div class="native-gap"><strong>Команда включена в каталог оригинала.</strong><p>Поля этого окна ещё не перенесены по результатам наблюдений. Подмены типовым окном с произвольными параметрами здесь нет.</p><p>Математическая операция не подключена.</p></div>`;
 const preset=spec?.preset?'<div class="native-preset"><button type="button" data-native-preset>По умолчанию <b>⌄</b></button><button type="button" data-native-unverified aria-label="Добавить набор параметров">+</button><button type="button" data-native-unverified aria-label="Действия с набором параметров">⋮</button></div>':'';
 box.innerHTML=`<header class="native-param-header"><button type="button" data-native-collapse aria-label="${collapsed?'Развернуть':'Свернуть'} панель" aria-expanded="${!collapsed}">${collapsed?'+':'−'}</button><span>${esc((spec?.title||ui.label(current)).toLocaleUpperCase('ru'))}</span><button type="button" data-native-dock title="Действие кнопки закрепления ещё проверяется" aria-label="Закрепление панели — проверка">»</button></header><div class="native-param-content" ${collapsed?'hidden':''}>${preset}<div class="native-param-fields">${body}</div><footer class="native-param-footer"><span class="native-info" tabindex="0" title="Воспроизведение интерфейса. Геометрическое ядро не подключено; подтверждение операции недоступно.">i</span><button type="button" class="native-ok" disabled>ОК</button><button type="button" data-native-cancel>Отмена</button></footer></div><span class="native-resize" tabindex="0" role="separator" aria-label="Изменить ширину панели"></span>`;
 box.hidden=false;if(spec?.family==='construction')box.querySelector('.native-pick')?.classList.add('selecting');clamp();
}
function clamp(){if(box.hidden)return;const r=box.getBoundingClientRect();if(!pos)pos={x:innerWidth-r.width-8*dip,y:Math.min(296*dip,innerHeight-r.height-55*dip)};pos.x=Math.max(0,Math.min(pos.x,innerWidth-r.width));pos.y=Math.max(35,Math.min(pos.y,innerHeight-r.height-8));box.style.left=pos.x+'px';box.style.top=pos.y+'px';}
function open(id){ui.closeMenus();if(current!==id)collapsed=false;current=id;if(!states.has(id)){const s={};for(const f of schemas[id]?.fields||[])s[f.id]=f.value;states.set(id,s);}render();box.dataset.inspection=schemas[id]?'native-default-state':'not-yet-transcribed';}
function close(){ui.closeMenus();box.hidden=true;current=null;document.querySelectorAll('.native-tool.selected').forEach(b=>b.classList.remove('selected'));}
box.addEventListener('click',e=>{e.stopPropagation();const c=e.target.closest('[data-native-cancel]');if(c){close();return;}if(e.target.closest('[data-native-collapse]')){collapsed=!collapsed;render();return;}if(e.target.closest('[data-native-dock]')){toast('Поведение кнопки закрепления ещё проверяется по оригиналу.');return;}const opt=e.target.closest('[data-native-option]');if(opt){changeField(opt.dataset.nativeOption,opt.dataset.optionValue);return;}const b=e.target.closest('[data-native-field]');if(b){const f=schemas[current].fields.find(f=>f.id===b.dataset.nativeField);ui.choose(b,f.name,f.options,data()[f.id],v=>changeField(f.id,v),f.id==='method'?(v=>window.asaNativeConstruction.commandArt(window.asaNativeConstruction.methodIcon(current,v),18)):null);return;}const sec=e.target.closest('[data-native-section]');if(sec){data()[sec.dataset.nativeSection]=!data()[sec.dataset.nativeSection];render();return;}if(e.target.closest('[data-native-select]')){box.querySelectorAll('.native-pick').forEach(x=>x.classList.remove('selecting'));e.target.closest('button').classList.add('selecting');window.dispatchEvent(new CustomEvent('asa-cad:native-selection-request',{detail:{nativeCommandId:current,field:e.target.closest('button').dataset.nativeSelect,referenceOnly:true}}));return;}if(e.target.closest('[data-native-preset],[data-native-unverified]')){toast('Состояния наборов параметров ещё проходят проверку по оригиналу.');}});
box.addEventListener('change',e=>{const b=e.target.closest('[data-native-check]');if(b)data()[b.dataset.nativeCheck]=b.checked;});
box.addEventListener('pointerdown',e=>{const head=e.target.closest('.native-param-header'),resize=e.target.closest('.native-resize');if((!head||e.target.closest('button'))&&!resize)return;e.preventDefault();ui.closeMenus();const r=box.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:r.left,top:r.top,width:r.width,resize:!!resize};box.setPointerCapture(e.pointerId);});
box.addEventListener('pointermove',e=>{if(!drag)return;if(drag.resize){box.style.width=Math.max(250,Math.min(innerWidth-drag.left,drag.width+e.clientX-drag.x))+'px';}else{pos={x:drag.left+e.clientX-drag.x,y:drag.top+e.clientY-drag.y};clamp();}});
function endDrag(e){if(!drag)return;if(drag.resize&&current)widths.set(current,box.getBoundingClientRect().width);drag=null;if(box.hasPointerCapture(e.pointerId))box.releasePointerCapture(e.pointerId);}
box.addEventListener('pointerup',endDrag);box.addEventListener('pointercancel',endDrag);
window.asaNativeDialogs={open,close,clamp,isOpen:()=>!box.hidden,getState:()=>({commandId:current,values:current?{...data()}:null,collapsed,kernelConnected:false}),schemas};
})();
